import boto3

from.security_models import NormalizeResponse


class SecurityClient:
    def __init__(self, region_name=None):
        self.client = boto3.client('secretsmanager', region_name=region_name)

    def get_secret_value(self, secret_id):
        response = self.client.get_secret_value(SecretId=secret_id)
        return NormalizeResponse(response)

class NormalizeResponse:
    def __init__(self, response):
        self.response = response

    def get_secret_string(self):
        return self.response['SecretString'] if 'SecretString' in self.response else self.response['SecretBinary'].decode('utf-8')

import json

from.security_client import SecurityClient


def fetch_db_secret(payload, config=None):
    client = SecurityClient(region_name=config.get('region'))
    response = client.get_secret_value(secret_id=payload['secret_id'])
    value = response.get_secret_string()
    if payload.get('key_field'):
        value = json.loads(value)[payload['key_field']]
    return {'db_secret': value}

from.security_client import SecurityClient


def rotate_secret_version(payload, config=None):
    client = SecurityClient(region_name=config.get('region'))
    response = client.get_secret_value(secret_id=payload['secret_id'], VersionStage='AWSCURRENT')
    return {'secret_version': response.get_secret_string()}

import boto3


def rotation_summary(payload, config=None):
    client = boto3.client('secretsmanager', region_name=config.get('region'))
    response = client.describe_secret(SecretId=payload['secret_id'])
    return {'rotation_enabled': response['RotationEnabled']}

import re


def secret_label_safety(payload):
    unsafe_patterns = [r'password', r'secret', r'key']
    for pattern in unsafe_patterns:
        if re.search(pattern, payload['label'], re.IGNORECASE):
            return {'safe': False}
    return {'safe': True}

import boto3


def secret_audit_embedding(payload, config=None):
    client = boto3.client('comprehend', region_name=config.get('region'))
    response = client.detect_sentiment(Text=payload['audit_note'], LanguageCode='en')
    return {'sentiment': response['Sentiment']}

import boto3


def runbook_translate(payload, config=None):
    client = boto3.client('translate', region_name=config.get('region'))
    response = client.translate_text(Text=payload['runbook_note'], SourceLanguageCode='en', TargetLanguageCode=payload['target_language'])
    return {'translated_text': response['TranslatedText']}
